    expect(manager.summary().counts.connected).toBe(1);
  });

  it("failed 态：error 详情投影（浮窗红字展示来源）", async () => {
    const { manager, entry } = await projectionBase();
    entry.status = "failed";
    entry.error = new Error("spawn pcmd ENOENT");
