  /** 进入「已失败一次、已安排续连 timer」的形态（超限将发生在下一次）。 */
  function pendingFixture() {
    const { sup, log } = agingFixture();
    sup.connectedAt = Date.now();
    sup.scheduleReconnect(new Error("again"));
