    manager.uiConfigSource = () => persistedSettings;
    manager.uiUpdate = async (patch) => {
      // 模拟 settings.update 行为：合并 patch，不抹除不在 patch 中的字段
      persistedSettings = { ...persistedSettings, ...patch };
